using UnityEngine;
using UnityEditor;

public class AssignIcons2
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();
        string basePath = "Assets/Herbal/";

        void AssignItemIcon(string itemName, string iconName)
        {
            var item = AssetDatabase.LoadAssetAtPath<InventoryItem>(basePath + itemName + ".asset");
            var icon = AssetDatabase.LoadAssetAtPath<Sprite>(basePath + iconName + ".png");
            if (item != null && icon != null)
            {
                item.icon = icon;
                EditorUtility.SetDirty(item);
                sb.AppendLine("[OK] InventoryItem Icon assigned: " + itemName);
            }
        }

        // Assign unique root icons
        AssignItemIcon("Jahe", "JaheIcon");
        AssignItemIcon("Kunyit", "KunyitIcon");
        AssignItemIcon("Kencur", "RootIcon"); // Re-use RootIcon for others since generation limited
        AssignItemIcon("Temulawak", "RootIcon");
        AssignItemIcon("Lengkuas", "RootIcon");

        // Assign Seed generic icon (RootIcon)
        string[] guids = AssetDatabase.FindAssets("t:InventoryItem", new[] { "Assets/Herbal" });
        Sprite genericSeed = AssetDatabase.LoadAssetAtPath<Sprite>(basePath + "RootIcon.png");
        foreach(var g in guids)
        {
            var item = AssetDatabase.LoadAssetAtPath<InventoryItem>(AssetDatabase.GUIDToAssetPath(g));
            if (item != null && item.itemType == InventoryItem.ItemType.Seed && genericSeed != null)
            {
                item.icon = genericSeed;
                EditorUtility.SetDirty(item);
            }
        }

        // 2. Assign RecipeImage
        string[] recipeGuids = AssetDatabase.FindAssets("t:CookingRecipe", new[] { "Assets/Herbal/Recipes" });
        foreach(var g in recipeGuids)
        {
            var recipe = AssetDatabase.LoadAssetAtPath<CookingRecipe>(AssetDatabase.GUIDToAssetPath(g));
            if (recipe != null && recipe.resultItem != null)
            {
                recipe.recipeImage = recipe.resultItem.icon;
                EditorUtility.SetDirty(recipe);
                sb.AppendLine("[OK] Recipe image synced from resultItem for: " + recipe.recipeName);
            }
        }

        // 3. Update ingredients in all recipes to fetch latest icons
        foreach(var g in recipeGuids)
        {
            var recipe = AssetDatabase.LoadAssetAtPath<CookingRecipe>(AssetDatabase.GUIDToAssetPath(g));
            if (recipe != null && recipe.ingredients != null)
            {
                foreach(var ing in recipe.ingredients)
                {
                    var itemRef = AssetDatabase.LoadAssetAtPath<InventoryItem>(basePath + ing.itemName + ".asset");
                    if (itemRef != null)
                    {
                        ing.itemIcon = itemRef.icon;
                    }
                }
                EditorUtility.SetDirty(recipe);
            }
        }

        AssetDatabase.SaveAssets();
        return sb.ToString();
    }
}
